import requests

def test_authentication_login_returns_token_and_user_on_valid_credentials():
    url = "http://localhost:3000/api/auth/login"
    payload = {
        "username": "jose",
        "password": "password123"
    }
    headers = {
        "Content-Type": "application/json"
    }
    try:
        response = requests.post(url, json=payload, headers=headers, timeout=30)
    except requests.RequestException as e:
        assert False, f"Request failed with exception: {e}"
    assert response.status_code == 200, f"Expected status code 200, got {response.status_code}"
    try:
        data = response.json()
    except ValueError:
        assert False, "Response is not valid JSON"
    assert "token" in data and isinstance(data["token"], str) and data["token"], "Missing or invalid token in response"
    assert "user" in data and isinstance(data["user"], dict), "Missing or invalid user object in response"
    user = data["user"]
    assert "id" in user and isinstance(user["id"], int), "User id is missing or not an integer"
    assert "username" in user and user["username"] == "jose", "User username is missing or does not match"
    assert "fullName" in user and isinstance(user["fullName"], str) and user["fullName"], "User fullName is missing or invalid"
    assert "role" in user and isinstance(user["role"], str) and user["role"], "User role is missing or invalid"

test_authentication_login_returns_token_and_user_on_valid_credentials()
